792	    std::lock_guard write_lock(write_mtx_);
793	
794	    if (writing_segment_->doc_count() != 0) {
795	      // flush and create new segment
796	      auto s = switch_to_new_segment_for_writing();
797	      if (!s.ok()) {
798	        return s;
799	      }
800	    }
