311	  if (schema_ != nullptr && options_.read_only_) {
312	    return Status::InvalidArgument(
313	        "Unable to create collection with read-only mode.");
314	  }
315	
316	  Status s;
317	  if (schema_ == nullptr) {
318	    // recovery from disk
319	    s = recovery();
320	  } else {
321	    // create new collection with existing schema
322	    s = create();
323	  }
324	
