2197	Status SegmentImpl::dump() {
2198	  if (sealed_) {
2199	    return Status::NotSupported("Segment has been dumped.");
2200	  }
2201	  auto s = flush();
2202	  CHECK_RETURN_STATUS(s);
2203	
2204	  if (invert_indexers_) {
2205	    s = invert_indexers_->seal();
2206	    CHECK_RETURN_STATUS(s);
2207	  }
2208	
2209	  s = dump_fts_indexers();
2210	  CHECK_RETURN_STATUS(s);
2211	
2212	  sealed_ = true;
2213	
2214	  return Status::OK();
2215	}
2216	
2217	Status SegmentImpl::flush() {
2218	  CHECK_SEGMENT_READONLY_RETURN_STATUS;
2219	
2220	  if (wal_file_ == nullptr || !wal_file_->has_record()) {
2221	    return Status::OK();
2222	  }
2223	
2224	  if (wal_file_) {
2225	    if (wal_file_->flush() != 0) {
2226	      LOG_ERROR("WAL flush failed: segment[%d]", id());
2227	      return Status::InternalError("Failed to flush wal");
2228	    }
2229	  }
2230	
2231	  Status s;
2232	
2233	  if (memory_store_) {
2234	    s = memory_store_->flush();
2235	    CHECK_RETURN_STATUS(s);
2236	  }
2237	
2238	  // flush scalar indexer
2239	  if (invert_indexers_) {
2240	    s = invert_indexers_->flush();
2241	    CHECK_RETURN_STATUS(s);
2242	  }
2243	
2244	  // flush FTS indexers
2245	  if (has_fts_) {
2246	    s = flush_fts_indexers();
2247	    CHECK_RETURN_STATUS(s);
2248	  }
2249	
2250	  // flush vector indexer
2251	  for (const auto &indexer : memory_vector_indexers_) {
2252	    if (indexer.second) {
2253	      s = indexer.second->Flush();
2254	      CHECK_RETURN_STATUS(s);
2255	    }
2256	  }
2257	
2258	  // flush quant vector indexer
2259	  for (const auto &indexer : quant_memory_vector_indexers_) {
2260	    if (indexer.second) {
2261	      s = indexer.second->Flush();
2262	      CHECK_RETURN_STATUS(s);
2263	    }
2264	  }
2265	
2266	  if (id_map_) {
2267	    s = id_map_->flush();
2268	    CHECK_RETURN_STATUS(s);
2269	  }
2270	
